llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Gallopamil, a close verapamil-class analogue sharing the dimethoxyphenethyl-N-methyl scaffold, showed 96.3% oral bioavailability in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Verapamil, the closest analogue with the same left-side scaffold, showed low oral bioavailability of approximately 20% in normal subjects due to extensive first-pass metabolism; this is the main contradictory evidence, but it is borderline at the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vernakalant, a structurally related basic ether with a cyclic amine, showed absolute oral bioavailability of 58 ± 19% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Drotaverine, a dimethoxyphenyl-containing drug, showed mean absolute bioavailability of 58.2 ± 18.2%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Bevantolol, a dimethoxyphenethylamine derivative, showed mean oral bioavailability of 57% (range 26–98%), supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence from verapamil-class and related basic drugs indicates F >= 20%. The only low evidence, verapamil, is borderline near the threshold and is outweighed by gallopamil and multiple other analogues with clearly high oral bioavailability.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule.",
    "Verapamil's oral bioavailability is borderline near the 20% threshold, making its contradictory direction less definitive.",
    "The effect of the benzazepinone lactam moiety on first-pass metabolism and permeability is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

